      "properties": {
        "resource": {
          "type": "string",
          "format": "topic",
          "axRole": "outlet"
        },
        "include": {
          "type": "array",
          "description": "List of categories to include to the resource."
        }
      }
    },
    "repository": {
      "type": "object",
      "description": "Action to get the releases and changelogs of the requested repository",
      "properties": {
        "action": {
          "type": "string",
          "format": "topic",
          "axRole": "inlet"
        }
      }
    },
    "getAll": {
      "type": "object",
      "description": "Action to get all releases and changelogs",
      "properties": {
        "action": {
          "type": "string",
          "format": "topic",
          "axRole": "inlet"
        }
      }
    }
  }
}

