          "name": "string",
          "minLength": 1
        },
        "property": {
          "type": "object",
          "minProperties": 1,
          "additionalProperties": false,
          "properties": {
            "viewInRecordSet": {
              "type": "boolean"
            }
          }
        }
      },
      "required": [
        "code",
        "name"
      ]
    },
    "serviceTypes": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/serviceType"
      }
    },
    "annotationKeys": {
      "type": "array",
