  "title": "Tree container",
  "description": "Testing chained containers",
  "$ref": "#/definitions/LevelOneContainer",
  "definitions": {
    "Item": {
      "properties": {
        "name": {
          "type": "string"
        },
        "value": {
          "type": "integer"
        }
